SourceCode.Declaration:
/// <summary>
/// Context class for customer MDF pricing, used to pass necessary information for customer MDF calculation and pricing when WMS is involved. This class is used in the scenario of finishing picking in WMS, where we need to trigger customer MDF calculation and repricing for the orders involved in picking.
/// </summary>
public class METCustomerMDFPricingContext implements System.IDisposable
{
    static METCustomerMDFPricingContext instance;

}

Method.Source:
/// <summary>
/// new instance of <c>METCustomerMDFPricingContext</c>. This will set the current context to this new instance. Nesting of this context is not supported and will throw an error if attempted.
/// </summary>
public void new()
{
    if (instance)
    {
        throw Error ("Nesting of METCustomerMDFPricingContext is not supported.");
    }
    instance = this;
}

/// <summary>
/// dispose the current context, setting the current instance to null. This should be called in a finally block to ensure the context is cleared even if errors occur.
/// </summary>
public void dispose()
{
    instance = null;
}

/// <summary>
/// current instance of the <c>METCustomerMDFPricingContext</c>. This will return the current context instance, which can be used to access any information stored in the context for customer MDF calculation and pricing. If no context is set, this will return null.
/// </summary>
/// <returns>Instance</returns>
static public METCustomerMDFPricingContext current()
{
    return instance;
}
